  // INCREMENTS — Increment_data, First_half, Second_half, Granted, Un_granted, Dakar_Increment_data, Not_in_Dakar_data
  // ═══════════════════════════════════════════════════════════════
  const INCREMENT_DATA = D.PEOPLE.slice(0, 50).map((p, i) => {
    const month = r(1, 12);
    const granted = pick([1,1,1,1,0,0]); // 1=granted, 0=pending, others below
    const withheld = rand() > 0.93;
    return {
      autoId: 7000 + i,
      idCard: p.idCard,
      name: `${p.name} ${p.surname}`,
      salScale: `${p.lastSalScale}/${r(1,7)}`,
      newSalScale: `${p.lastSalScale}/${r(2,8)}`,
      presentSalary: 21000 + r(0, 8000),
      newSalary: 21500 + r(0, 8500),
      fromDate: `2026-${String(month).padStart(2,"0")}-01`,
      dakarGrade: p.gradeDesc,
      prsGrade: p.gradeDesc,
      sentToOfficer: rand() > 0.2,
      approvedIncrements: granted === 1 && rand() > 0.3,
      uploaded: rand() > 0.5,
      sentToDakar: rand() > 0.6,
      sentToSRS: rand() > 0.5,
      officer: pick(["borgm196","camis087","spitc188","farrr149","mifsk221"]),
      dateAdded: `2026-04-${String(r(1,28)).padStart(2,"0")}`,
      incGranted: !withheld,
      teachingNonTeaching: p.teaching ? 0 : 2,
      yearForInc: 2026,
      markedWithheld: withheld,
      withheldReason: withheld ? pick(["Disciplinary action pending","Performance review pending","Long-term unpaid leave","Awaiting probation confirmation"]) : null,
      half: month <= 6 ? "first" : "second",
      isGozo: p.paypoint.startsWith("59/"),
    };
  });
  const NOT_IN_DAKAR = D.PEOPLE.slice(50, 53).map((p, i) => ({
    idCard: p.idCard,
    name: `${p.name} ${p.surname}`,
    grade: p.gradeDesc,
    commencDate: p.commencDate,
    reason: pick(["Recently appointed — DAKAR sync pending","Returned from career break","Detail in process"]),
  }));

