  // ── Termination_Data rows (per officer) ─────────────────────────
  const _chkTechNonTeach = (pos) => {
    const m = TEACHING_GRADES.find(g => g.posi === pos);
    return m ? m.techOrNonTeach : 2;
  };
  const mkTermRows = (officerName, slice, defaultType) => D.PEOPLE.slice(slice[0], slice[1]).map((p, i) => {
    const reason = pick(TERMINATION_REASONS.filter(r => r.analiseShow));
    const tnT = _chkTechNonTeach(p.gradeDesc) || (defaultType === "T" ? 1 : 2);
    return {
      id: r(2000, 9999) + i,
      personIdno: p.idCard,
      name: `${p.name} ${p.surname}`,
      gradePosition: p.gradeDesc,
      reason: reason.reasonEng,
      genReason: reason.genericReason,
      terminationComments: "",
      terminationDate: `2026-${String(r(1,9)).padStart(2,"0")}-${String(r(1,28)).padStart(2,"0")}`,
      sex: p.gender,
      teachingNonTeaching: tnT,
      college: p.paypointDesc.split(",")[0],
      primarySecondary: rand() > 0.5 ? "Secondary" : "Primary",
      terminationResignation: pick(["Termination","Resignation"]),
      officer: officerName,
      prsRecAutoId: r(310000, 312000),
      prsRemAutoId: r(20000, 22000),
      sectionsInformed: rand() > 0.4,
      emailComments: "",
      dbName: "Terminations",
    };
  });
  const TERM_CARMEN  = mkTermRows("spitc188", [10, 22], "T");
  const TERM_RUDOLPH = mkTermRows("farrr149", [22, 32], "NT");

